// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // First configure flash governance so assertGovernanceApproved can pass
        // We'll use vm.prank to become a successful proposal
        // But simpler: we just need to see that after endConfiguration, configured differs
        // So call endConfiguration, then read configured
        c.endConfiguration();
        bool configuredNow = c.configured();
        assertTrue(configuredNow == true); // P: true, M: false
    }
}

