pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // scenario: call assertGovernanceApproved(this, this, false)
        // reference: configured = true after constructor, so flash governance check reverts
        // bug: configured = false, so the revert path is skipped and governance proceeds
        address target = address(this);
        bool ok;
        try c.assertGovernanceApproved(address(this), target, false) {
            ok = true;
        } catch {
            ok = false;
        }
        // assert that the bug (configured=false) leads to a different outcome
        // We don't know the exact outcome, but we can assert the configured value directly
        // since the bug sets it to false and reference sets it to true
        assertTrue(c.configured());
    }
}

