pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // The bug: endConfiguration() sets configured = false instead of true
        // After deploy, configured is true in reference (constructor calls setDAO which sets DAO = address(this); configured is false by default)
        // Actually constructor does not set configured. Let's check: after deploy, configured is false in both.
        // To trigger divergence, call setDAO from a non-DAO address after configured becomes true.
        // But the difference is in endConfiguration: reference sets true, bug sets false.
        // So call endConfiguration first.
        c.endConfiguration();
        // Now in reference configured = true, in bug configured = false.
        // Now call assertGovernanceApproved from an address that is not DAO and not governed.
        // In reference (configured=true), the governance check will run and revert because sender not successful proposal.
        // In bug (configured=false), the governance check is skipped and the flash governance logic proceeds.
        address attacker = address(0x123);
        vm.prank(attacker);
        // This will revert in reference but not in buggy
        bool ok;
        try c.assertGovernanceApproved(attacker, address(this), false) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, ok = false (revert). In bug, ok = true (no revert).
        assertTrue(!ok, "Reference should revert");
    }
}

