pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: DAO calls setGoverned to whitelist address(1) as governed
        address governedCaller = address(0x1);
        address[] memory governables = new address[](1);
        governables[0] = governedCaller;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        // Configure flash governance with some asset/amount/unlockTime
        IERC20 dummyAsset = IERC20(address(0xdead));
        vm.mockCall(address(dummyAsset), abi.encodeWithSelector(IERC20.transferFrom.selector), abi.encode(true));
        c.configureFlashGovernance(address(dummyAsset), 1 ether, 3600, false);

        // Warp to allow flash governance (epoch checks)
        vm.warp(block.timestamp + 10000);

        // Prank as governed caller and call assertGovernanceApproved
        vm.prank(governedCaller);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.assertGovernanceApproved.selector, governedCaller, address(0x2), false));

        // In reference (configured=true) it reverts because sender not successful proposal;
        // In bug (configured=false) it does not revert.
        assertTrue(!ok, "Reference reverts, bug does not");
    }
}

