// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Use a non-DAO address to call setDAO
        address nonDAO = address(0x1234);
        vm.prank(nonDAO);
        // On reference: succeeds (DAO becomes address(0))
        // On buggy: reverts (require(msg.sender == DAO) fails)
        // We need to catch revert on buggy; use try/catch to handle both
        bool success;
        try c.setDAO(address(0)) {
            success = true;
        } catch {
            success = false;
        }
        // After call, DAO will differ:
        // If call succeeded, DAO is address(0)
        // If call failed, DAO is still address(this)
        // Assert that DAO == address(0) — true on reference, false on buggy
        assertTrue(c.DAO() == address(0));
    }
}

